#!/usr/bin/env node
/**
 * Bundles the canonical legal markdown into a TypeScript module the app can
 * render offline. Run after editing anything in docs/legal/.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SOURCE_DIR = path.join(ROOT, 'docs', 'legal');
const TARGET = path.join(ROOT, 'src', 'assets', 'legal', 'legalDocs.ts');

const documents = {
  PRIVACY_POLICY: 'privacy-policy.md',
  TERMS_OF_SERVICE: 'terms-of-service.md',
  OPEN_SOURCE_NOTICES: 'open-source-notices.md',
};

const lines = [
  '// Generated by scripts/sync-legal-docs.js — do not edit directly.',
  '// Edit the markdown files in docs/legal/ and re-run `yarn legal:sync`.',
  '',
];

for (const [constant, file] of Object.entries(documents)) {
  const text = fs.readFileSync(path.join(SOURCE_DIR, file), 'utf8').trimEnd();
  lines.push(`export const ${constant} = ${JSON.stringify(text)};`, '');
}

fs.mkdirSync(path.dirname(TARGET), {recursive: true});
fs.writeFileSync(TARGET, `${lines.join('\n').trimEnd()}\n`);
console.log(`Wrote ${path.relative(ROOT, TARGET)}`);
